LLVMOrcThreadSafeModuleRef createDemoModule(void) {
  // Create an LLVMContext.
  LLVMContextRef Ctx = LLVMContextCreate();

  // Create a new LLVM module.
  LLVMModuleRef M = LLVMModuleCreateWithNameInContext("demo", Ctx);

